// //// Neoffice — added file (no upstream equivalent): Nora's sphere, drawn from the design system's own geometry.

//! Nora's sphere: the one icon of Nora everywhere (design system, `assets/icons/nora-orb.svg`). The SVG is thirteen
//! rings of latitude of running dust (a dash of 0.01 with round caps is a dot); its geometry is in `orb_rings.rs`
//! (generated by `tools/gen_orb.py`), and this draws it: the near half of each ring strong and moving one way, the far
//! half faint and moving the other, the whole sphere breathing. Without a clock it is the rest pose, which is what the
//! SVG shows under `prefers-reduced-motion`: a pane that waits for the person repaints nothing for it.

use std::sync::OnceLock;

use egui::{Color32, Painter, Pos2, Rect, pos2};

use crate::orb_rings::RINGS;

/// One ring of the sphere, in the SVG's 64 by 64 units.
pub(crate) struct Ring {
    pub rotate: f32,
    /// The dot's diameter (the stroke's width).
    pub width: f32,
    pub cx: f32,
    pub cy: f32,
    pub rx: f32,
    pub ry: f32,
    /// The length of the dash pattern, and where in it a dot sits.
    pub period: f32,
    pub starts: &'static [f32],
    pub front_offset: f32,
    pub back_offset: f32,
    /// How long a dot takes to run one pattern.
    pub seconds: f32,
}

const STEPS: usize = 32;
const VIEW: f32 = 64.0;
/// How strong the near half of a ring is, and the far half (the SVG's opacities).
const NEAR: f32 = 0.95;
const FAR: f32 = 0.35;
/// The sphere breathes from 1 to 1.04 in 4.2 s.
const BREATH_SECONDS: f32 = 4.2;

/// The length of a half ring up to each step of its angle, so that a dot is placed by the distance it ran.
fn lengths() -> &'static Vec<[f32; STEPS + 1]> {
    static TABLE: OnceLock<Vec<[f32; STEPS + 1]>> = OnceLock::new();
    TABLE.get_or_init(|| {
        RINGS
            .iter()
            .map(|ring| {
                let mut table = [0.0; STEPS + 1];
                let mut at = 0.0;
                for (step, length) in table.iter_mut().enumerate().skip(1) {
                    let phi = std::f32::consts::PI * (step as f32 - 0.5) / STEPS as f32;
                    let speed = (ring.rx * phi.sin()).hypot(ring.ry * phi.cos());
                    at += speed * std::f32::consts::PI / STEPS as f32;
                    *length = at;
                }
                table
            })
            .collect()
    })
}

/// The angle (0 at the left end of a half ring, π at the right end) reached after `distance` along it.
fn angle_at(table: &[f32; STEPS + 1], distance: f32) -> f32 {
    let step = table.partition_point(|&length| length < distance).clamp(1, STEPS);
    let (from, to) = (table[step - 1], table[step]);
    let share = if to > from { ((distance - from) / (to - from)).clamp(0.0, 1.0) } else { 0.0 };
    std::f32::consts::PI * (step as f32 - 1.0 + share) / STEPS as f32
}

/// Draws the sphere in `rect` in `color`. `seconds` is the clock of the animation (`None`: the rest pose).
pub fn paint(painter: &Painter, rect: Rect, color: Color32, seconds: Option<f32>) {
    let side = rect.width().min(rect.height());
    if !side.is_finite() || side <= 0.0 {
        return;
    }
    let unit = side / VIEW;
    let origin = rect.center() - egui::vec2(side, side) / 2.0;
    let breath = seconds.map_or(1.0, |t| 1.0 + 0.02 * (1.0 - (std::f32::consts::TAU * t / BREATH_SECONDS).cos()));
    let tables = lengths();
    for (ring, table) in RINGS.iter().zip(tables) {
        let total = table[STEPS];
        let (sin_r, cos_r) = ring.rotate.to_radians().sin_cos();
        let run = seconds.map_or(0.0, |t| ring.period / ring.seconds * t);
        for (near, strength) in [(true, NEAR), (false, FAR)] {
            // A dot's place on the half ring: where the pattern put it, moved by the time (the near half runs the way
            // the path goes, the far half the other way).
            let (offset, shift) = if near { (ring.front_offset, run) } else { (ring.back_offset, -run) };
            let tint = color.gamma_multiply(strength);
            for start in ring.starts {
                // The first place of this dot on the path, then one every period.
                let mut distance = (start - offset + shift).rem_euclid(ring.period);
                while distance <= total {
                    let phi = angle_at(table, distance);
                    let x = ring.cx - ring.rx * phi.cos();
                    let y = if near { ring.cy + ring.ry * phi.sin() } else { ring.cy - ring.ry * phi.sin() };
                    // The ring is turned a little about the centre of the sphere, then the sphere breathes.
                    let (dx, dy) = (x - 32.0, y - 32.0);
                    let (rx, ry) = (dx * cos_r - dy * sin_r, dx * sin_r + dy * cos_r);
                    let at: Pos2 = pos2(origin.x + (32.0 + rx * breath) * unit, origin.y + (32.0 + ry * breath) * unit);
                    painter.circle_filled(at, (ring.width * breath * unit / 2.0).max(0.45), tint);
                    distance += ring.period;
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_sphere_has_thirteen_rings_like_the_svg() {
        assert_eq!(RINGS.len(), 13);
        assert!(RINGS.iter().all(|ring| ring.period > 0.0 && ring.seconds > 0.0 && !ring.starts.is_empty()));
    }

    #[test]
    fn a_dot_run_along_a_ring_stays_on_it() {
        let table = &lengths()[6];
        let total = table[STEPS];
        assert!(total > 0.0);
        assert!(angle_at(table, 0.0) < 0.2);
        assert!((angle_at(table, total) - std::f32::consts::PI).abs() < 0.1);
        // Further along the path is a larger angle.
        assert!(angle_at(table, total * 0.75) > angle_at(table, total * 0.25));
    }

    #[test]
    fn the_sphere_is_drawn_at_rest_and_in_motion_and_never_in_nothing() {
        let ctx = egui::Context::default();
        let mut output = ctx.run_ui(egui::RawInput::default(), |ui| {
            let rect = Rect::from_min_size(pos2(0.0, 0.0), egui::vec2(28.0, 28.0));
            paint(ui.painter(), rect, Color32::BLACK, None);
            paint(ui.painter(), rect, Color32::BLACK, Some(1.7));
            paint(ui.painter(), Rect::NOTHING, Color32::BLACK, Some(1.0));
            paint(ui.painter(), Rect::from_min_size(pos2(0.0, 0.0), egui::vec2(0.0, 0.0)), Color32::BLACK, None);
        });
        output.textures_delta.clear();
    }
}
